    CUSTOMER_ID NUMBER(38,0) NOT NULL,
    CUSTOMER_NAME VARCHAR,
    EMAIL VARCHAR,
    CUSTOMER_TIER VARCHAR
);

CREATE TABLE IF NOT EXISTS DEV_DB.BRONZE.ORDERS (
    ORDER_ID NUMBER(38,0) NOT NULL,
    CUSTOMER_ID NUMBER(38,0),
    ORDER_DATE DATE,
    ORDER_AMOUNT NUMBER(12,2),
